(function(n){n.JobLabContent=Object.assign(n.JobLabContent||{},{"KK-711":{scenario:{company:"Thanh Mai General Hospital",supervisor:{name:"Ninh Thị Bảo Trâm",role:{vi:"Trưởng khoa Dược",en:"Head of Pharmacy"}},ref_code:"DL-3308",title:{vi:"Đúng thuốc. Đúng liều. An toàn người bệnh.",en:"Right drug. Right dose. Patient safety first."},brief:{vi:"Đây là tình huống đào tạo. Bạn là dược sĩ lâm sàng khoa Nội, duyệt đơn DL-3308 của người bệnh nữ 76 tuổi, nặng 72 kg, creatinin huyết thanh 0,8 mg/dL, viêm phổi cộng đồng. Đơn mới kê clarithromycin 500 mg x 2 lần/ngày trong khi người bệnh đang dùng simvastatin 40 mg buổi tối. Đối chiếu phiếu can thiệp dược nháp với tài liệu gốc, sửa mức độ tương tác và độ thanh thải creatinin, rồi lập báo cáo đề xuất cho bác sĩ.",en:"This is a training scenario. As the internal medicine clinical pharmacist you review order DL-3308 for a 76-year-old woman, 72 kg, serum creatinine 0.8 mg/dL, with community-acquired pneumonia. The new order adds clarithromycin 500 mg twice daily while she takes simvastatin 40 mg every evening. Compare the draft intervention form with the source documents, correct the interaction severity and the creatinine clearance, then write a recommendation for the physician."},reference_title:{vi:"Dữ liệu tương tác & hồ sơ cận lâm sàng",en:"Interaction database & laboratory record"},fields:[{id:"DDI_LEVEL",label:{vi:"Mức độ tương tác thuốc",en:"Drug interaction severity"},initial:"MODERATE",expected:"CONTRAINDICATED",choices:["MINOR","MODERATE","CONTRAINDICATED"],reference:"Cơ sở dữ liệu tương tác thuốc",ref_value:{vi:"Clarithromycin (ức chế mạnh CYP3A4) + simvastatin: chống chỉ định phối hợp (CONTRAINDICATED), nguy cơ tiêu cơ vân",en:"Clarithromycin (strong CYP3A4 inhibitor) + simvastatin: CONTRAINDICATED combination, rhabdomyolysis risk"},hint:{vi:"Simvastatin chuyển hóa chủ yếu qua CYP3A4; chất ức chế mạnh làm nồng độ statin tăng nhiều lần.",en:"Simvastatin is mainly cleared by CYP3A4; a strong inhibitor raises statin levels several-fold."}},{id:"CRCL",label:{vi:"Độ thanh thải creatinin (mL/phút)",en:"Creatinine clearance (mL/min)"},initial:"80",expected:"68",reference:"Phiếu xét nghiệm & sinh hiệu",ref_value:{vi:"Nữ, 76 tuổi, cân nặng thực 72 kg, creatinin huyết thanh 0,8 mg/dL",en:"Female, 76 years, actual body weight 72 kg, serum creatinine 0.8 mg/dL"},hint:{vi:"Công thức Cockcroft-Gault có hệ số hiệu chỉnh riêng cho người bệnh nữ.",en:"The Cockcroft-Gault formula has a correction factor for female patients."}}],sop32:{vi:"Cockcroft-Gault: CrCl (mL/phút) = (140 - tuổi) x cân nặng (kg) / (72 x creatinin huyết thanh mg/dL); nhân thêm 0,85 nếu là nữ. Ghi kết quả vào phiếu can thiệp trước khi đề xuất liều.",en:"Cockcroft-Gault: CrCl (mL/min) = (140 - age) x weight (kg) / (72 x serum creatinine mg/dL); multiply by 0.85 for women. Record it on the intervention form before recommending a dose."},context:{label:"HIS / DL-3308",metrics:[{label:{vi:"Tuổi (nữ)",en:"Age (female)"},value:"76"},{label:{vi:"Cân nặng",en:"Weight"},value:"72 kg"},{label:{vi:"Creatinin huyết thanh",en:"Serum creatinine"},value:"0.8 mg/dL"},{label:{vi:"Thuốc đang dùng",en:"Current statin"},value:"simvastatin 40 mg"}]},crisis:{vi:"Bác sĩ điều trị nhắn: “Cứ cấp phát nguyên đơn, bà ấy dùng simvastatin lâu rồi không sao. Đừng ghi phiếu can thiệp kẻo khoa bị trừ điểm chất lượng, có gì tôi chịu.”",en:"The attending physician messages you: “Dispense the order as written, she has taken simvastatin for years without problems. Do not file an intervention form or the ward loses quality points. I will take responsibility.”"},options:{safe:{vi:"Không cấp phát phối hợp chống chỉ định, trao đổi trực tiếp với bác sĩ, đề xuất tạm ngừng simvastatin trong đợt kháng sinh hoặc đổi kháng sinh phù hợp, ghi phiếu can thiệp và báo Trưởng khoa Dược.",en:"Do not dispense the contraindicated pair, talk to the physician directly, propose pausing simvastatin during the antibiotic course or a suitable alternative, file the intervention and inform the Head of Pharmacy."},shortcut:{vi:"Cấp phát nguyên đơn theo lời bác sĩ và không ghi phiếu can thiệp.",en:"Dispense the order as the physician says and skip the intervention form."},wait:{vi:"Giữ đơn lại không xử lý và chờ bác sĩ tự phát hiện tương tác.",en:"Hold the order without action and wait for the physician to notice the interaction."}},questions:{vi:["Vì sao phối hợp clarithromycin với simvastatin được xếp CONTRAINDICATED và CrCl 68 mL/phút có ý nghĩa gì với người bệnh này?","Bạn trao đổi với bác sĩ và ghi nhận can thiệp thế nào để vừa an toàn người bệnh vừa đúng quy định dược lâm sàng?"],en:["Why is clarithromycin with simvastatin rated CONTRAINDICATED, and what does a CrCl of 68 mL/min mean for this patient?","How do you discuss it with the physician and document the intervention so the patient is safe and pharmacy rules are met?"]},hints:{vi:["Tra cơ chế tương tác qua enzym chuyển hóa và đối chiếu mức độ trong cơ sở dữ liệu gốc.","Kiểm tra giới tính người bệnh trước khi áp dụng công thức Cockcroft-Gault ở SOP mục 3.2.","Đọc lại SOP mục 4.2: tương tác nguy hiểm phải được can thiệp, ghi nhận và báo cáo, không bỏ qua theo lời nhắn."],en:["Look up the metabolic mechanism and match the severity in the source database.","Check the patient's sex before applying Cockcroft-Gault in SOP 3.2.","Re-read SOP 4.2: a dangerous interaction must be acted on, documented and escalated, never ignored on request."]}},learning:{summary:{vi:"Dược sĩ lâm sàng và dược sĩ cộng đồng bảo đảm người bệnh dùng thuốc an toàn, hợp lý và hiệu quả. Tại bệnh viện, dược sĩ duyệt đơn, phát hiện tương tác, hiệu chỉnh liều theo chức năng gan thận, theo dõi phản ứng có hại và tham gia hội chẩn. Tại nhà thuốc, dược sĩ tư vấn, bán thuốc theo đơn đúng quy định và hướng dẫn người bệnh tuân thủ điều trị.",en:"Clinical and community pharmacists make sure patients use medicines safely, rationally and effectively. In hospital they review orders, detect interactions, adjust doses to renal and hepatic function, monitor adverse reactions and join ward rounds. In community pharmacies they counsel patients, dispense prescription-only medicines lawfully and support adherence."},responsibilities:{vi:["Duyệt đơn thuốc: chỉ định, liều, đường dùng, tương tác, chống chỉ định trước khi cấp phát.","Hiệu chỉnh liều theo chức năng thận, gan, tuổi và cân nặng của người bệnh.","Theo dõi, ghi nhận và báo cáo phản ứng có hại của thuốc (ADR) theo quy định.","Tư vấn cho bác sĩ, điều dưỡng và người bệnh về cách dùng, bảo quản và tuân thủ điều trị.","Tham gia Hội đồng Thuốc và điều trị, xây dựng danh mục và hướng dẫn sử dụng kháng sinh."],en:["Review orders for indication, dose, route, interactions and contraindications before dispensing.","Adjust doses for renal and hepatic function, age and body weight.","Monitor, record and report adverse drug reactions (ADR) as required.","Advise physicians, nurses and patients on use, storage and adherence.","Serve on the Drug and Therapeutics Committee and help build the formulary and antibiotic guidance."]},competencies:[{name:{vi:"Dược lý lâm sàng",en:"Clinical pharmacology"},desc:{vi:"Nắm dược động học, dược lực học và cơ chế tương tác để đánh giá nguy cơ trên từng người bệnh.",en:"Apply pharmacokinetics, pharmacodynamics and interaction mechanisms to judge risk for each patient."}},{name:{vi:"Tính toán liều",en:"Dose calculation"},desc:{vi:"Tính CrCl, liều theo cân nặng, diện tích da và hiệu chỉnh liều chính xác.",en:"Calculate CrCl, weight- and BSA-based doses and dose adjustments accurately."}},{name:{vi:"Tra cứu bằng chứng",en:"Evidence retrieval"},desc:{vi:"Dùng dược thư, tờ hướng dẫn sử dụng và cơ sở dữ liệu tương tác tin cậy, ghi rõ nguồn.",en:"Use formularies, product labels and reliable interaction databases and cite the source."}},{name:{vi:"Giao tiếp chuyên môn",en:"Professional communication"},desc:{vi:"Đề xuất can thiệp ngắn gọn, có căn cứ và phương án thay thế để bác sĩ dễ chấp nhận.",en:"Make concise, evidence-based recommendations with alternatives that physicians can accept."}},{name:{vi:"Đạo đức hành nghề",en:"Professional ethics"},desc:{vi:"Đặt an toàn người bệnh lên trước, không bán thuốc kê đơn khi không có đơn, không bỏ qua cảnh báo.",en:"Put patient safety first, never sell prescription-only drugs without a prescription or ignore alerts."}}],knowledge:{vi:["Luật Dược số 105/2016/QH13 và các văn bản hướng dẫn hiện hành.","Nghị định 131/2020/NĐ-CP về tổ chức, hoạt động dược lâm sàng của cơ sở khám bệnh, chữa bệnh.","Thông tư 02/2018/TT-BYT về Thực hành tốt cơ sở bán lẻ thuốc (GPP).","Công thức Cockcroft-Gault và nguyên tắc hiệu chỉnh liều theo chức năng thận.","Tương tác dược động học qua hệ enzym CYP450, đặc biệt CYP3A4 và CYP2C9.","Tiêu chí Beers về thuốc có nguy cơ không phù hợp ở người cao tuổi."],en:["Pharmacy Law No. 105/2016/QH13 and its current implementing documents.","Decree 131/2020/ND-CP on clinical pharmacy organization and practice in healthcare facilities.","Circular 02/2018/TT-BYT on Good Pharmacy Practice for retail outlets (GPP).","The Cockcroft-Gault formula and renal dose adjustment principles.","Pharmacokinetic interactions via CYP450 enzymes, especially CYP3A4 and CYP2C9.","The Beers Criteria for potentially inappropriate medications in older adults."]},tools:["Phần mềm duyệt đơn trên HIS","Cơ sở dữ liệu tương tác thuốc","Dược thư Quốc gia Việt Nam","Công cụ tính liều theo chức năng thận","Phần mềm quản lý nhà thuốc GPP"],kpis:{vi:["Tỷ lệ đơn nội trú được duyệt trước khi cấp phát.","Tỷ lệ can thiệp dược được bác sĩ chấp nhận.","Số ADR được phát hiện và báo cáo đúng hạn.","Số sai sót thuốc đến người bệnh do bỏ sót tương tác (mục tiêu bằng 0)."],en:["Share of inpatient orders reviewed before dispensing.","Share of pharmacist interventions accepted by physicians.","ADRs detected and reported on time.","Medication errors reaching patients from missed interactions (target zero)."]},day:[{time:"07:30",vi:"Duyệt đơn mới trên HIS, lọc cảnh báo tương tác và liều cao.",en:"Review new orders in the HIS and screen interaction and high-dose alerts."},{time:"09:00",vi:"Đi buồng cùng bác sĩ, xem xét nghiệm chức năng thận, gan của người bệnh nặng.",en:"Join ward rounds and check renal and liver results of high-risk patients."},{time:"11:00",vi:"Ghi phiếu can thiệp dược, đề xuất hiệu chỉnh liều hoặc thuốc thay thế.",en:"File intervention forms proposing dose changes or alternatives."},{time:"14:00",vi:"Tư vấn người bệnh ra viện về cách dùng thuốc và dấu hiệu cần tái khám.",en:"Counsel discharged patients on how to take medicines and warning signs."},{time:"16:00",vi:"Tổng hợp ADR, cập nhật bản tin thông tin thuốc cho các khoa.",en:"Compile ADR reports and update the drug information bulletin for wards."}],mistakes:{vi:["Quên hệ số 0,85 cho người bệnh nữ khi tính Cockcroft-Gault.","Chỉ xem cảnh báo của phần mềm mà không đánh giá cơ chế và bối cảnh người bệnh.","Cấp phát theo lời nhắn miệng dù đơn có phối hợp chống chỉ định."],en:["Forgetting the 0.85 factor for women in Cockcroft-Gault.","Relying on software alerts without judging the mechanism and the patient's context.","Dispensing on a verbal request despite a contraindicated combination."]},career:[{vi:"Dược sĩ nhà thuốc / dược sĩ cấp phát",en:"Community / dispensing pharmacist"},{vi:"Dược sĩ lâm sàng",en:"Clinical pharmacist"},{vi:"Dược sĩ lâm sàng chuyên khoa / Trưởng bộ phận dược lâm sàng",en:"Specialist clinical pharmacist / Clinical pharmacy lead"},{vi:"Trưởng khoa Dược bệnh viện",en:"Hospital Head of Pharmacy"}],glossary:[{term:"CrCl",vi:"Độ thanh thải creatinin, ước tính chức năng lọc của thận để hiệu chỉnh liều thuốc.",en:"Creatinine clearance, an estimate of renal filtration used to adjust drug doses."},{term:"ADR",vi:"Phản ứng có hại của thuốc: đáp ứng độc hại, không mong muốn ở liều thông thường.",en:"Adverse drug reaction: a harmful, unintended response at normal doses."},{term:"CYP3A4",vi:"Enzym gan chuyển hóa nhiều thuốc; bị ức chế bởi clarithromycin, ketoconazol, nước bưởi chùm.",en:"Liver enzyme that metabolizes many drugs; inhibited by clarithromycin, ketoconazole and grapefruit juice."},{term:"Can thiệp dược",vi:"Đề xuất của dược sĩ nhằm thay đổi điều trị để giải quyết vấn đề liên quan đến thuốc.",en:"A pharmacist recommendation that changes therapy to resolve a drug-related problem."},{term:"GPP",vi:"Thực hành tốt cơ sở bán lẻ thuốc: chuẩn về nhân sự, cơ sở, quy trình và tư vấn tại nhà thuốc.",en:"Good Pharmacy Practice: standards for staff, premises, procedures and counselling in pharmacies."}],quiz:[{q:{vi:"Nam 68 tuổi, 60 kg, creatinin huyết thanh 1,5 mg/dL. CrCl theo Cockcroft-Gault là bao nhiêu?",en:"A 68-year-old man, 60 kg, serum creatinine 1.5 mg/dL. What is his Cockcroft-Gault CrCl?"},options:{vi:["34 mL/phút","48 mL/phút","40 mL/phút","60 mL/phút"],en:["34 mL/min","48 mL/min","40 mL/min","60 mL/min"]},answer:2,explain:{vi:"(140 - 68) x 60 / (72 x 1,5) = 4320 / 108 = 40 mL/phút; nam không nhân 0,85.",en:"(140 - 68) x 60 / (72 x 1.5) = 4320 / 108 = 40 mL/min; no 0.85 factor for men."}},{q:{vi:"Xử trí hợp lý khi người bệnh dùng simvastatin cần đợt clarithromycin là gì?",en:"What is a sound approach when a patient on simvastatin needs a course of clarithromycin?"},options:{vi:["Tạm ngừng simvastatin trong đợt kháng sinh hoặc chọn kháng sinh khác","Tăng liều simvastatin","Dùng cả hai và không theo dõi","Ngừng hẳn statin vĩnh viễn"],en:["Pause simvastatin during the course or choose another antibiotic","Increase the simvastatin dose","Give both without monitoring","Stop the statin permanently"]},answer:0,explain:{vi:"Phối hợp chống chỉ định do nguy cơ tiêu cơ vân; tạm ngừng statin hoặc đổi kháng sinh là phương án an toàn.",en:"The pair is contraindicated due to rhabdomyolysis risk; pausing the statin or switching antibiotic is safe."}},{q:{vi:"Khách đến nhà thuốc xin mua kháng sinh không có đơn vì “lần trước uống khỏi”. Bạn làm gì?",en:"A customer asks to buy an antibiotic without a prescription because “it worked last time”. What do you do?"},options:{vi:["Bán số lượng ít để khách đỡ phiền","Bán loại kháng sinh rẻ hơn","Bán nếu khách cam kết đi khám sau","Từ chối bán, tư vấn triệu chứng và hướng dẫn đi khám"],en:["Sell a small amount to please them","Sell a cheaper antibiotic","Sell if they promise to see a doctor later","Decline, counsel on symptoms and refer them to a doctor"]},answer:3,explain:{vi:"Kháng sinh là thuốc kê đơn; bán không đơn vi phạm quy định và thúc đẩy kháng kháng sinh.",en:"Antibiotics are prescription-only; selling without a prescription is unlawful and drives resistance."}},{q:{vi:"Tiêu chí Beers được dùng để làm gì?",en:"What are the Beers Criteria used for?"},options:{vi:["Tính liều cho trẻ em","Nhận diện thuốc có nguy cơ không phù hợp ở người cao tuổi","Phân loại thuốc gây nghiện","Đánh giá giá thuốc đấu thầu"],en:["Pediatric dosing","Identifying potentially inappropriate drugs in older adults","Classifying narcotics","Assessing tender prices"]},answer:1,explain:{vi:"Beers liệt kê thuốc nên tránh hoặc thận trọng ở người cao tuổi để giảm biến cố bất lợi.",en:"Beers lists drugs to avoid or use with caution in older adults to reduce adverse events."}}],tools_en:["HIS prescription review module","Drug interaction database","Vietnam National Drug Formulary","Renal function dose calculator","GPP pharmacy management software"]}}})})(window.KKR);
